const hre = require("hardhat");

async function main() {
  const Uniswapv2 = await hre.ethers.getContractFactory("Uniswapv2");
  const uniswapv2 = await Uniswapv2.deploy();

  await uniswapv2.deployed();

  console.log("Uniswapv2 deployed to:", uniswapv2.address);
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});